mapper.select:
select r.stock_code as stockCode, r.low_date as lowDate, k.close_price as closePrice from stock_rising_low r inner join ( select stock_code, max(low_date) as maxLowDate from stock_rising_low where stock_code in
#{code}
group by stock_code ) t on r.stock_code = t.stock_code and r.low_date = t.maxLowDate inner join stock_kline k on k.stock_code = r.stock_code and k.kline_type = 'D' and date(k.trade_time) = r.low_date
